def can_chain(dominoes):
    """Return a closed chain of dominoes, or None if no chain exists.

    A chain is valid when adjacent halves match and the free ends of the
    first and last stones match each other.
    """
    if not dominoes:
        return []

    for i, domino in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        for first in (domino, (domino[1], domino[0])):
            chain = _chain(rest, first[1], first[0], [first])
            if chain is not None:
                return chain
    return None


def _chain(rest, end, start, chain):
    """Try to extend `chain` (whose current right end is `end`) with the
    remaining dominoes in `rest`, closing the loop at `start`."""
    if not rest:
        return chain if end == start else None

    for i, domino in enumerate(rest):
        for placed in (domino, (domino[1], domino[0])):
            if placed[0] == end:
                chain = _chain(
                    rest[:i] + rest[i + 1:], placed[1], start, chain + [placed]
                )
                if chain is not None:
                    return chain
    return None

